import {GROUPS} from './config.js?v=4.0.0';
import {quoteService,RECONVERSION_DOMAINS} from './services.js?v=4.0.0';
import {escapeHTML as esc} from './v40-view.js?v=4.0.0';
const names={physical:'Préparateur physique',recovery:'Récupération',proximity:'Résidence proche du club',installation:'Installation personnelle',maintenance:'Entretien de l’installation',formation:'Préparer l’après-carrière'};
const money=n=>Number(n||0).toLocaleString('fr-FR',{maximumFractionDigits:2})+' €';
export function servicesView(s,{quote=null,message='',busy=false,installationDomain='Physique',formationDomain='coaching'}={}){
 const active=s.v40.services.active;
 return `<section class="panel services"><p class="eyebrow">INVESTIR DANS VOTRE CARRIÈRE</p><h2>Votre accompagnement</h2><p>Solde : <b>${money(s.money)}</b> · Réserve protégée : ${money(s.life.finance.reserve)}</p><p class="muted">Monnaie virtuelle du jeu. Les services complètent votre travail quotidien.</p>${message?`<p role="status">${esc(message)}</p>`:''}<div class="services-grid">${Object.entries(names).map(([kind,name])=>{
 const domain=kind==='formation'?formationDomain:installationDomain,q=quoteService(s,kind,{domain}),c=active[kind];
 return `<article class="service-card"><h3>${name}</h3><strong>${money(q.price)}</strong><p>${esc(q.effects)}</p>${['installation','formation'].includes(kind)?`<label>Domaine<select id="service-domain-${kind}" ${busy||c?'disabled':''}>${Object.entries(kind==='formation'?RECONVERSION_DOMAINS:Object.fromEntries(Object.keys(GROUPS).map(k=>[k,k]))).map(([id,label])=>`<option value="${esc(id)}" ${id===domain?'selected':''}>${esc(label)}</option>`).join('')}</select></label>`:''}${c?`<p class="data-note">${kind==='formation'?`${c.sessions}/30 séances · ${c.hours}/60 heures`:`Actif à partir du jour ${c.start}${c.end?' · payé jusqu’au jour '+c.end:''}`}</p>`:''}${!q.ok?`<p class="muted">${esc(q.reason)}</p>`:''}<button id="service-open-${kind}" data-action="service-open:${kind}" ${busy||!q.ok?'disabled':''}>Voir le devis</button>${kind==='recovery'&&c?`<label class="check"><input type="checkbox" id="recovery-renew" ${c.renew?'checked':''} ${busy?'disabled':''}> Renouveler pour 900 € / 30 jours</label>`:''}</article>`;
 }).join('')}</div>${quote?`<section class="service-confirm" id="service-confirm" tabindex="-1" aria-label="Confirmation de service"><h3>Confirmer : ${esc(names[quote.kind])}</h3><p>Débit immédiat : <b>${money(quote.price)}</b></p><p>Solde après achat : ${money(s.money-quote.price)} · réserve : ${money(s.life.finance.reserve)}</p><p>${esc(quote.effects)}</p><p>${esc(quote.conditions)}</p><button data-action="service-confirm" ${busy||!quote.ok?'disabled':''}>Confirmer l’achat</button><button data-action="service-cancel">Annuler</button></section>`:''}<details><summary>Bilan des services</summary><p>Dépenses hors coaching : ${money(s.v40.services.totals.paid)} · fatigue récupérée : ${Number(s.v40.services.totals.recovery||0).toFixed(1)} · XP d’installation : ${s.v40.services.totals.extraXP||0}</p>${(s.v40.services.qualifications||[]).map(q=>`<p>Qualification : ${esc(RECONVERSION_DOMAINS[q.domain])} · ${q.hours} heures</p>`).join('')}${s.v40.services.history.slice().reverse().map(c=>`<p>${esc(names[c.kind])} · ${esc(c.reason)}${c.sessions!==undefined?' · '+c.sessions+' séances':''}</p>`).join('')}</details></section>`;
}
